#!/usr/bin/env bash
# Install the pose/motion gateway (8766) as a systemd unit, but do not enable
# or start it. Motion requires an explicit operator start.
#
# Run as root on the robot, with this deploy/ directory copied to the robot:
#   sudo bash install-pose-gateway.sh
#
# Prerequisites:
#   - the read-only 8765 gateway was installed (shared token file exists);
#   - /home/pi/docker/tmp/armpi_gateway_pose/takeover_limits.json exists
#     (generated by tools/export_gateway_motion_config.py).
set -euo pipefail

if [[ ${EUID} -ne 0 ]]; then
  echo "ERROR: run as root (sudo bash install-pose-gateway.sh)" >&2
  exit 1
fi

SELF_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
SRC_DIR=$(cd "${SELF_DIR}/.." && pwd)
HOST_DEPLOY_DIR="${ARMPI_GATEWAY_POSE_HOST_DEPLOY_DIR:-/home/pi/docker/tmp/armpi_gateway_pose}"
TOKEN_FILE="${ARMPI_GATEWAY_HOST_DEPLOY_DIR:-/home/pi/docker/tmp/armpi_gateway_deploy}/token"
MOTION_CONFIG="${HOST_DEPLOY_DIR}/takeover_limits.json"
INSTALL_DIR=/usr/local/lib/armpi-gateway
ENV_DIR=/etc/armpi-gateway
UNIT_PATH=/etc/systemd/system/armpi-gateway-pose.service
SERVICE_USER="${ARMPI_GATEWAY_SERVICE_USER:-pi}"
SERVICE_GROUP="${ARMPI_GATEWAY_SERVICE_GROUP:-docker}"

if ! id -u "${SERVICE_USER}" >/dev/null 2>&1; then
  echo "ERROR: service user ${SERVICE_USER} does not exist" >&2
  exit 1
fi
if ! getent group "${SERVICE_GROUP}" >/dev/null 2>&1; then
  echo "ERROR: service group ${SERVICE_GROUP} does not exist" >&2
  exit 1
fi
RUNUSER_BIN=$(command -v runuser || true)
if [[ -z "${RUNUSER_BIN}" ]]; then
  echo "ERROR: runuser is required to check the service account" >&2
  exit 1
fi
if ! timeout 10 "${RUNUSER_BIN}" -u "${SERVICE_USER}" -- docker info >/dev/null 2>&1; then
  echo "ERROR: ${SERVICE_USER} cannot access the Docker daemon (docker group)" >&2
  exit 1
fi
if [[ ! -s "${TOKEN_FILE}" ]]; then
  echo "ERROR: shared token missing: ${TOKEN_FILE}" >&2
  echo "Run install-gateway.sh first." >&2
  exit 1
fi
if [[ ! -s "${MOTION_CONFIG}" ]]; then
  echo "ERROR: motion limits missing: ${MOTION_CONFIG}" >&2
  echo "Generate it with tools/export_gateway_motion_config.py and copy it." >&2
  exit 1
fi

install -d -m 755 "${HOST_DEPLOY_DIR}" "${INSTALL_DIR}" "${ENV_DIR}"

rm -rf "${HOST_DEPLOY_DIR}/armpi_debug_gateway"
cp -a "${SRC_DIR}/armpi_debug_gateway" "${HOST_DEPLOY_DIR}/armpi_debug_gateway"
find "${HOST_DEPLOY_DIR}/armpi_debug_gateway" -name __pycache__ -type d -prune -exec rm -rf {} +

install -m 755 "${SELF_DIR}/armpi-gateway-pose-run.sh" \
  "${INSTALL_DIR}/armpi-gateway-pose-run.sh"
UNIT_TMP=$(mktemp)
sed \
  -e "s|@ARMPI_SERVICE_USER@|${SERVICE_USER}|g" \
  -e "s|@ARMPI_SERVICE_GROUP@|${SERVICE_GROUP}|g" \
  "${SELF_DIR}/armpi-gateway-pose.service" > "${UNIT_TMP}"
install -m 644 "${UNIT_TMP}" "${UNIT_PATH}"
rm -f "${UNIT_TMP}"

if [[ ! -f "${ENV_DIR}/pose.env" ]]; then
  install -m 640 -g "${SERVICE_GROUP}" \
    "${SELF_DIR}/pose.env.example" "${ENV_DIR}/pose.env"
  echo "created ${ENV_DIR}/pose.env"
else
  chgrp "${SERVICE_GROUP}" "${ENV_DIR}/pose.env"
  chmod 640 "${ENV_DIR}/pose.env"
fi

systemctl daemon-reload
echo "installed ${UNIT_PATH} (not enabled)"
echo "start explicitly with: sudo systemctl start armpi-gateway-pose"
echo "verify with: curl -H \"X-Armpi-Token: <token>\" http://10.42.0.218:8766/health"
